// TH15 st04.ecl.txt MainSub00 (879-896) + ECir00 (8-42) + ECir00_at (44-93).
// Synthetic training card; source DIFF 0..3 maps to GVAR_RANK 0..3.
const TIME_LIMIT: int = 1224;      // 120 opening + 1100 source-window estimate + 4 startup
const OPENING_BUFFER: int = 120;
const TH15_RICE: int = 480;        // source type 8 (TH15 type -> modern slot reuse)

// Source MainSub00: ECir00 formation, 2 per group on Easy/Normal, 4 on Hard/Lunatic,
// groups at source t=0 and t=40 (enmCreate coordinates are world coordinates here).
async sub wave_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-128fx, 128fx, 600, 0, 1000, 0, ecir00);
    _ = spawn_enemy(128fx, 128fx, 600, 0, 1000, 0, ecir00);
    if global(GVAR_RANK) >= 2 {
        _ = spawn_enemy(-170fx, 128fx, 600, 0, 1000, 0, ecir00);
        _ = spawn_enemy(170fx, 128fx, 600, 0, 1000, 0, ecir00);
    }
    wait(40);
    _ = spawn_enemy(-160fx, 192fx, 600, 0, 1000, 0, ecir00);
    _ = spawn_enemy(160fx, 192fx, 600, 0, 1000, 0, ecir00);
    if global(GVAR_RANK) >= 2 {
        _ = spawn_enemy(-40fx, 64fx, 600, 0, 1000, 0, ecir00);
        _ = spawn_enemy(40fx, 64fx, 600, 0, 1000, 0, ecir00);
    }
    wait(120);
}

// Source ECir00: training enemy is invulnerable, body/hurt boxes kept as source circles.
// movePosRel(0,32) + movePosRelTime(120,1,0,0) is the 120-frame birth slide and is omitted
// by the approved birth-animation policy; it finishes exactly when firing starts.
async sub ecir00() {
    set_invuln(65535);
    set_hurtbox(12fx);   // source setHurtbox(24,24): ordinary circle r = 24/2
    set_hitbox(8fx);     // source setHitbox(16,16): ordinary circle r = 16/2
    wait(120);
    spawn ecir00_at();
    wait(180);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);  // source moveVel(ANGLE_PLAYER, 0)
    move_speed(120, 1fx, EASE_LINEAR);            // source moveSpeedTime(120, mode0, 1.0)
    loop { wait(1000); }                          // source ECir00_712/732 endless 1000-frame loop
}

// Source ECir00_at: aim mode 3 fixed-direction ring, 5 ways x 1 layer, angle step 2*pi/5.
// Per-volley alpha = ANGLE_PLAYER + RANDF2 * (1deg Easy, 10deg N/H/L); one sample per volley.
// Speed = 1.5/2.5/3.5/4.5 and B = 20/80/80/100 at intervals 10/5/5/4 (source difficulty masks).
async sub ecir00_at() {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var speed: fx = 1.5fx + (rank as fx);
    var amp: int = 1820;                  // 10deg in BAM
    if rank == 0 { amp = 182; }           // 1deg
    var volleys: int = 80;
    var interval: int = 5;
    if rank == 0 { volleys = 20; interval = 10; }
    else if rank == 3 { volleys = 100; interval = 4; }
    for v in 0..volleys {
        var off: int = (rand(65536) - 32768) * amp / 32768;  // RANDF2 in [-1,1), BAM
        var base: angle = aim_player() + (off as angle);
        var ex: fx = $self_x;
        var ey: fx = $self_y;
        for i in 0..5 {
            var a: angle = base + (((i * 65536) / 5) as angle);  // mode 3: alpha + 2*pi*i/N
            // Source EX type 2 (ANIM) birth offset: position -= 4 * velocity.
            _ = fire(TH15_RICE, 6, ex - 4fx * speed * cos(a), ey - 4fx * speed * sin(a), speed, a, none, none);
        }
        wait(interval);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
